html, body {
  overflow: hidden !important;
  margin: 0;
  padding: 0;
}

.app {
  width: 100%;
  font-family: system-ui;
  background: var(--appsmith-theme-panelColor, #0f172a);
  border-radius: 6px;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
  color: var(--appsmith-theme-textStrongColor, #ffffff);
  border-bottom: 2px solid var(--appsmith-theme-borderStrongColor, #64748b);
  font-weight: 600;
  width: 100%;
  box-sizing: border-box;
}

.sortIcon {
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  flex-shrink: 0;
}

.list {
  width: 100%;
  overflow: visible; /* remove internal scroll */
}

.row {
  padding: 7px 10px;
  cursor: pointer;
  color: var(--appsmith-theme-textStrongColor, #ffffff);
  font-size: 14px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  border-bottom: 2px solid var(--appsmith-theme-panelColor, #0f172a);
}

.row:nth-child(odd) {
  background: var(--dark-243447, var(--appsmith-theme-surfaceColor, #0f172a));
}

.row:nth-child(even) {
  background: var(--dark-1e293b, var(--appsmith-theme-surfaceColor, #0f172a));
}

.row:hover {
  background: var(--appsmith-theme-hoverStrongColor, #334155);
}

.selected {
  background: var(--appsmith-theme-accentColor, #86efac) !important;
  color: var(--appsmith-theme-surfaceColor, #0f172a);
}

